impl Display for Pinned {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        // registry+<package_name>?v<version>#<cid>!namespace
        write!(
            f,
            "{}+{}?{}#{}!{}",
            Self::PREFIX,
            self.source.name,
            self.source.version,
            self.cid.0,
            self.source.namespace
        )
    }
