    pub apply: bool,
    pub capture: bool,
    pub captured: Vec<Syscall>,
}

impl Default for EcalSyscallHandler {
    fn default() -> Self {
        Self::only_capturing()
    }
}

impl EcalSyscallHandler {
    pub fn only_capturing() -> Self {
        Self {
            apply: false,
            capture: true,
            captured: vec![],
        }
    }

    pub fn only_applying() -> Self {
        Self {
            apply: true,
            capture: false,
            captured: vec![],
        }
    }

    pub fn clear(&mut self) {
        self.captured.clear();
    }
}

