        let UploadedBytecode::Completed(returned_bytecode) = storage
            .read_transaction()
            .storage_as_ref::<UploadedBytecodes>()
            .get(&root)
            .unwrap()
            .unwrap()
            .into_owned()
        else {
            panic!("expected complete upload")
        };

        // Then
