    pub fn append_launch_config(
        &mut self,
        launch_config: &LaunchConfig,
        ctx: &mut ModelContext<Self>,
    ) {
        if !self.launch_configs.contains(launch_config) {
            self.launch_configs.push(launch_config.to_owned());
