pub fn is_tab_config_toml(path: &Path) -> bool {
    let is_toml = path
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension == "toml");
    if !is_toml {
        return false;
    }

    [tab_configs_dir(), default_tab_configs_dir()]
        .into_iter()
