                Some(PackageRoot::root(&package_root)),
                &settings.linter,
                Some(&cache),
                flags::Noqa::Enabled,
                flags::FixMode::Generate,
                UnsafeFixes::Enabled,
            )
            .unwrap();
        }

        assert_eq!(
            expected_diagnostics, got_diagnostics,
            "left == {expected_diagnostics:#?}, right == {got_diagnostics:#?}",
        );
    }

