        if tx.is_using_predicates() {
            tx.estimate_predicates(self, Some(latest_chain_executor_version))
                .await?;
            tx.clone()
                .validate_predicates(self.consensus_parameters(), latest_block_height)?;
        }

        self.validate_transaction(tx.clone()).await?;

        Ok(tx)
