    async fn maybe_estimate_predicates(
        &self,
        tx: &FuelTransaction,
        latest_chain_executor_version: Option<u32>,
    ) -> Result<Option<FuelTransaction>> {
        let latest_chain_executor_version = match latest_chain_executor_version {
