            None => {
                self.chain_info()
                    .await?
                    .latest_block
                    .header
                    .state_transition_bytecode_version
            }
        };

        Ok(
            (latest_chain_executor_version > LATEST_STATE_TRANSITION_VERSION)
                .then_some(self.client.estimate_predicates(tx).await?),
        )
    }
