    let tx_status = provider.send_transaction_and_await_commit(tx).await?;

    assert!(matches!(tx_status, TxStatus::Revert { .. }));

    let coins = wallet
        .get_spendable_resources(*provider.base_asset_id(), 1)
        .await?;
    assert_eq!(coins.len(), 1);

