                if !matches!(ir, IR::Sink { .. }) {
                    tmp_top = ir_arena.add(IR::Sink {
                        input: root,
                        payload: SinkTypeIR::Memory,
                    });
                }
                simplify_ordering::simplify_and_fetch_orderings(&[tmp_top], ir_arena, expr_arena);
            },
        }
    }

    expand_datasets::expand_datasets(root, ir_arena, expr_arena, apply_scan_predicate_to_scan_ir)?;

    // During debug we check if the optimizations have not modified the final schema.
    #[cfg(debug_assertions)]
    {
        // only check by names because we may supercast types.
        assert_eq!(
            prev_schema.iter_names().collect::<Vec<_>>(),
            ir_arena
                .get(root)
                .schema(ir_arena)
                .iter_names()
                .collect::<Vec<_>>()
        );
    };

    Ok(root)
}

fn _get_or_init_members<'a>(
    opt_members: &'a mut Option<MemberCollector>,
    root: Node,
    ir_arena: &mut Arena<IR>,
    expr_arena: &mut Arena<AExpr>,
) -> &'a mut MemberCollector {
    opt_members.get_or_insert_with(|| {
        let mut members = MemberCollector::new();
        members.collect(root, ir_arena, expr_arena);

        members
    })
}
```

## Issue / fix: feat: Add `maintain_order` parameter to `merge_sorted`

## Description
## Summary

Closes #27114.

Adds a `maintain_order: bool` parameter to `merge_sorted()`. When set to `True`, the output is guaranteed to have **left-biased ordering** for equal keys: rows from the left frame always appear before rows from the right frame when their keys match.

- Threads `maintain_order` through the full stack: Python API → PyO3 bindings → DSL/IR plan → streaming engine → in-memory engine
- Core streaming fix: `find_mergeable()` holds back right-side rows at chunk boundaries whose keys equal the left's maximum (uses `gt_eq` instead of `gt`), preventing right-side ties from being emitted before left-side ties arriving in later morsels
- The in-memory engine already produces left-biased output, so the flag is only load-bearing in the streaming path
- Defaults to `False` for backward compatibility

## Test plan

- [x] 3 new test functions (6 cases) covering both streaming and in-memory engines:
  - Basic left-biased ordering with overlapping keys
  - All keys identical
  - `DataFrame.merge_sorted()` API path
- [x] All 41 existing `merge_sorted` tests pass with no regressions
- [x] Rust `cargo check --features merge_sorted` passes

